3: //! Enables bindings that only activate under certain conditions,
4: //! such as "Tab indents when there's a selection".
5: 
6: use serde::Deserialize;
7: 
8: /// Context extracted from the application model for keybinding evaluation
9: #[derive(Debug, Clone, Default)]
10: pub struct KeyContext {
11:     /// Whether there's an active text selection
12:     pub has_selection: bool,
13:     /// Whether multiple cursors are active
14:     pub has_multiple_cursors: bool,
15:     /// Whether a modal dialog is open
16:     pub modal_active: bool,
17:     /// Whether the editor (vs modal input) has focus
18:     pub editor_focused: bool,
19: }
20: 
21: impl KeyContext {
22:     /// Create context indicating editor is focused with no special state
23:     pub fn editor_default() -> Self {
24:         Self {
25:             has_selection: false,
26:             has_multiple_cursors: false,
27:             modal_active: false,
28:             editor_focused: true,
29:         }
30:     }
31: 
32:     /// Create context for when a modal is active
33:     pub fn modal() -> Self {
34:         Self {
35:             has_selection: false,
36:             has_multiple_cursors: false,
37:             modal_active: true,
38:             editor_focused: false,
39:         }
40:     }
41: }
42: 
43: /// Conditions that can be attached to keybindings
44: ///
45: /// Multiple conditions on a binding are ANDed together.
46: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
47: #[serde(rename_all = "snake_case")]
48: pub enum Condition {
49:     /// Binding only active when text is selected
50:     HasSelection,
51:     /// Binding only active when no text is selected
52:     NoSelection,
53:     /// Binding only active with multiple cursors
54:     HasMultipleCursors,
55:     /// Binding only active with single cursor
56:     SingleCursor,
57:     /// Binding only active when a modal is open
58:     ModalActive,
59:     /// Binding only active when no modal is open
60:     ModalInactive,
61:     /// Binding only active when editor has focus
62:     EditorFocused,
63: }
64: 
65: impl Condition {
66:     /// Evaluate this condition against the current context
67:     pub fn evaluate(self, ctx: &KeyContext) -> bool {
68:         match self {
69:             Condition::HasSelection => ctx.has_selection,
70:             Condition::NoSelection => !ctx.has_selection,
71:             Condition::HasMultipleCursors => ctx.has_multiple_cursors,
72:             Condition::SingleCursor => !ctx.has_multiple_cursors,
73:             Condition::ModalActive => ctx.modal_active,
74:             Condition::ModalInactive => !ctx.modal_active,
75:             Condition::EditorFocused => ctx.editor_focused,
76:         }
77:     }
78: 
79:     /// Evaluate all conditions (AND logic)
80:     pub fn evaluate_all(conditions: &[Condition], ctx: &KeyContext) -> bool {
81:         conditions.iter().all(|c| c.evaluate(ctx))
82:     }
83: }
84: 
85: #[cfg(test)]
86: mod tests {
87:     use super::*;
88: 
89:     #[test]
90:     fn test_default_context() {
91:         let ctx = KeyContext::default();
92:         assert!(!ctx.has_selection);
93:         assert!(!ctx.has_multiple_cursors);
94:         assert!(!ctx.modal_active);
95:         assert!(!ctx.editor_focused);
96:     }
97: 
98:     #[test]
99:     fn test_editor_default_context() {
100:         let ctx = KeyContext::editor_default();
101:         assert!(!ctx.has_selection);
102:         assert!(ctx.editor_focused);
103:     }
104: 
105:     #[test]
106:     fn test_condition_has_selection() {
107:         let mut ctx = KeyContext::default();
108:         assert!(!Condition::HasSelection.evaluate(&ctx));
109:         assert!(Condition::NoSelection.evaluate(&ctx));
110: 
111:         ctx.has_selection = true;
112:         assert!(Condition::HasSelection.evaluate(&ctx));
113:         assert!(!Condition::NoSelection.evaluate(&ctx));
114:     }
115: 
116:     #[test]
117:     fn test_condition_multi_cursor() {
118:         let mut ctx = KeyContext::default();
119:         assert!(!Condition::HasMultipleCursors.evaluate(&ctx));
120:         assert!(Condition::SingleCursor.evaluate(&ctx));
121: 
122:         ctx.has_multiple_cursors = true;
123:         assert!(Condition::HasMultipleCursors.evaluate(&ctx));
124:         assert!(!Condition::SingleCursor.evaluate(&ctx));
125:     }
126: 
127:     #[test]
128:     fn test_condition_modal() {
129:         let ctx = KeyContext::modal();
130:         assert!(Condition::ModalActive.evaluate(&ctx));
131:         assert!(!Condition::ModalInactive.evaluate(&ctx));
132:         assert!(!Condition::EditorFocused.evaluate(&ctx));
133:     }
134: 
135:     #[test]
136:     fn test_evaluate_all_empty() {
137:         let ctx = KeyContext::default();
138:         assert!(Condition::evaluate_all(&[], &ctx));
139:     }
140: 
141:     #[test]
142:     fn test_evaluate_all_and_logic() {
143:         let mut ctx = KeyContext::editor_default();
144:         ctx.has_selection = true;
145: 
146:         // Both conditions true
147:         let conditions = vec![Condition::HasSelection, Condition::EditorFocused];
148:         assert!(Condition::evaluate_all(&conditions, &ctx));
149: 
150:         // One condition false
151:         let conditions = vec![Condition::HasSelection, Condition::HasMultipleCursors];
152:         assert!(!Condition::evaluate_all(&conditions, &ctx));
153:     }
154: }",
